from taf.sw.security.defensics.interfaces.Defensics_v2020_3.defensics_v2020_3 import DEFENSICS_v2020_3


class DefensicsVersionNotSupported(Exception):
    pass


class SupportedDefensicsVersions(object):
    defensics_v2020_3 = DEFENSICS_v2020_3


class DefensicsProvider(object):
    @classmethod
    def get_defensics_interface(cls, ip_address, port, token, defensics_version, secure):
        """
        Currently only supports defensics_v2020_3
        """
        defensics_interface = getattr(SupportedDefensicsVersions, defensics_version, None)
        if not defensics_interface:
            error_message = f"This version {defensics_version} is not supported"
            raise DefensicsVersionNotSupported(error_message)
        defensics_obj = defensics_interface(ip_address, port, token, secure)

        return defensics_obj
